INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-1000-0000-000000000001','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu as enfin réussi à monter ton étagère toute seule ?
[Femme] Oui, hier après-midi.
[Homme] Mais tu as fait comment ?
[Femme] ...

A. Pendant deux heures environ.
B. En suivant la notice étape par étape.
C. Parce que j''en avais vraiment besoin.
D. Dans le salon, contre le mur.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu as enfin réussi à monter ton étagère toute seule ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, hier après-midi.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Mais tu as fait comment ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Pendant deux heures environ.<break time="700ms"/>B.<break time="300ms"/>En suivant la notice étape par étape.<break time="700ms"/>C.<break time="300ms"/>Parce que j''en avais vraiment besoin.<break time="700ms"/>D.<break time="300ms"/>Dans le salon, contre le mur.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Les deux premiers tours plantent le contexte (le montage est terminé). La question finale « tu as fait comment ? » porte sur **la manière, la méthode employée**. Seule B « en suivant la notice étape par étape » (gérondif de moyen) y répond. A indique une **durée** (« combien de temps cela t''a-t-il pris ? »). C indique une **cause / motivation** (« pourquoi l''as-tu montée ? »). D indique un **lieu** (« où l''as-tu installée ? »). Piège B1 : les quatre réponses parlent bien du montage, seule la nature de la question (« comment ») permet de trancher.','[{"label": "Pendant deux heures environ.", "is_correct": false, "display_order": 1}, {"label": "En suivant la notice étape par étape.", "is_correct": true, "display_order": 2}, {"label": "Parce que j''en avais vraiment besoin.", "is_correct": false, "display_order": 3}, {"label": "Dans le salon, contre le mur.", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/795d7e15-63c0-40fd-a7db-49e862909f28.mp3','33','fr-FR-HenriNeural','2026-05-31 16:49:07.958123+02','b70fde1d-95a5-48f1-8b2a-001892218c3b','2026-05-27 17:40:30.299355+02','2026-05-31 16:49:29.204293+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-1000-0000-000000000002','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Ça y est, ton rendez-vous à la préfecture est confirmé.
[Homme] Oui. Et c''est pour quand exactement ?
[Femme] ...

A. Au guichet numéro quatre.
B. Pour renouveler mon titre de séjour.
C. Mercredi prochain, à dix heures.
D. Avec ma sœur qui m''accompagne.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Ça y est, ton rendez-vous à la préfecture est confirmé.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui. Et c''est pour quand exactement ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Au guichet numéro quatre.<break time="700ms"/>B.<break time="300ms"/>Pour renouveler mon titre de séjour.<break time="700ms"/>C.<break time="300ms"/>Mercredi prochain, à dix heures.<break time="700ms"/>D.<break time="300ms"/>Avec ma sœur qui m''accompagne.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour pose le sujet (un rendez-vous à la préfecture, déjà confirmé) ; le second contient la question implicite « pour quand exactement ? » qui porte sur **un moment précis**. Seule C « mercredi prochain, à dix heures » donne un point dans le temps. A indique un **lieu** dans la préfecture (« à quel guichet ? »). B exprime un **but / motif** (« pour quoi faire ? »). D précise l''**accompagnant** (« avec qui y vas-tu ? »). Toutes les réponses restent dans le champ administratif, ce qui rend le piège B1 réaliste.','[{"label": "Au guichet numéro quatre.", "is_correct": false, "display_order": 1}, {"label": "Pour renouveler mon titre de séjour.", "is_correct": false, "display_order": 2}, {"label": "Mercredi prochain, à dix heures.", "is_correct": true, "display_order": 3}, {"label": "Avec ma sœur qui m''accompagne.", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/2529e126-8253-46bc-9ce1-a0767bcf90fc.mp3','33','fr-FR-HenriNeural','2026-05-31 16:49:08.298129+02','b70fde1d-95a5-48f1-8b2a-001892218c3b','2026-05-27 17:40:30.299355+02','2026-05-31 16:49:29.719746+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-1000-0000-000000000003','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Léa a pleuré toute la soirée hier.
[Homme] Vraiment ? Elle qui est si calme d''habitude.
[Femme] Tu sais pourquoi ?
[Homme] ...

A. Pendant plus d''une heure, je crois.
B. À cause d''une dispute avec sa sœur.
C. Pour qu''on lui prête un peu d''attention.
D. Dans sa chambre, toute seule.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Léa a pleuré toute la soirée hier.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Vraiment ? Elle qui est si calme d''habitude.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu sais pourquoi ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Pendant plus d''une heure, je crois.<break time="700ms"/>B.<break time="300ms"/>À cause d''une dispute avec sa sœur.<break time="700ms"/>C.<break time="300ms"/>Pour qu''on lui prête un peu d''attention.<break time="700ms"/>D.<break time="300ms"/>Dans sa chambre, toute seule.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Les deux premiers tours installent l''étonnement (Léa pleure alors qu''elle est calme d''habitude), le troisième pose la question implicite « pourquoi ? », qui porte sur **la cause, ce qui a déclenché les pleurs**. Seule B « à cause d''une dispute » donne une cause antérieure. A donne une **durée** (« combien de temps a-t-elle pleuré ? »). C donne un **but** (« dans quel objectif pleurait-elle ? ») — piège B1 classique : confusion cause / but. D donne un **lieu** (« où était-elle ? »).','[{"label": "Pendant plus d''une heure, je crois.", "is_correct": false, "display_order": 1}, {"label": "À cause d''une dispute avec sa sœur.", "is_correct": true, "display_order": 2}, {"label": "Pour qu''on lui prête un peu d''attention.", "is_correct": false, "display_order": 3}, {"label": "Dans sa chambre, toute seule.", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/58065788-11e9-4d9d-9d06-b7cbb8846bc0.mp3','35','fr-FR-HenriNeural','2026-05-31 16:49:08.625795+02','b70fde1d-95a5-48f1-8b2a-001892218c3b','2026-05-27 17:40:30.299355+02','2026-05-31 16:49:31.420171+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-1000-0000-000000000004','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] J''ai enfin trouvé une superbe robe pour le mariage de ma cousine !
[Femme] Ah, génial. Tu l''as dénichée où ?
[Homme] ...

A. Avec ma mère, samedi dernier.
B. Plutôt longue, avec des manches.
C. Pour environ quatre-vingts euros.
D. Dans une petite boutique du centre-ville.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''ai enfin trouvé une superbe robe pour le mariage de ma cousine !</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Ah, génial. Tu l''as dénichée où ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Avec ma mère, samedi dernier.<break time="700ms"/>B.<break time="300ms"/>Plutôt longue, avec des manches.<break time="700ms"/>C.<break time="300ms"/>Pour environ quatre-vingts euros.<break time="700ms"/>D.<break time="300ms"/>Dans une petite boutique du centre-ville.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour fixe le sujet (une robe pour un mariage déjà trouvée) ; le second pose la question implicite « tu l''as dénichée où ? », qui porte sur **le lieu d''achat**. Seule D « dans une petite boutique du centre-ville » désigne un lieu. A donne un **accompagnant et un moment** (« avec qui et quand ? »). B donne une **description** de la robe (« comment est-elle ? »). C donne un **prix** (« combien l''as-tu payée ? »). Toutes les pistes restent crédibles dans un échange sur les achats.','[{"label": "Avec ma mère, samedi dernier.", "is_correct": false, "display_order": 1}, {"label": "Plutôt longue, avec des manches.", "is_correct": false, "display_order": 2}, {"label": "Pour environ quatre-vingts euros.", "is_correct": false, "display_order": 3}, {"label": "Dans une petite boutique du centre-ville.", "is_correct": true, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/f8fe2a5f-f134-4585-b576-637a6c3639ca.mp3','34','fr-FR-DeniseNeural','2026-05-31 16:49:08.932951+02','b70fde1d-95a5-48f1-8b2a-001892218c3b','2026-05-27 17:40:30.299355+02','2026-05-31 16:49:32.039806+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-1000-0000-000000000005','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu as fait toutes les courses pour la fête de ce soir ?
[Homme] Oui, je rentre tout juste du supermarché.
[Femme] Et tu as pris combien de bouteilles de vin ?
[Homme] ...

A. Du rouge et un peu de blanc.
B. Six, comme on s''était dit.
C. Pour à peu près trente euros.
D. Chez le caviste de la place.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu as fait toutes les courses pour la fête de ce soir ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui, je rentre tout juste du supermarché.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Et tu as pris combien de bouteilles de vin ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Du rouge et un peu de blanc.<break time="700ms"/>B.<break time="300ms"/>Six, comme on s''était dit.<break time="700ms"/>C.<break time="300ms"/>Pour à peu près trente euros.<break time="700ms"/>D.<break time="300ms"/>Chez le caviste de la place.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Les deux premiers tours fixent le contexte (les courses sont déjà faites). La question implicite « combien de bouteilles ? » porte sur **un nombre**. Seule B « six » donne une quantité. A renvoie au **type de vin** (« quel vin ? »). C renvoie au **prix total** (« combien as-tu dépensé ? »). D renvoie au **lieu d''achat** (« où les as-tu achetées ? ») — piège B1 : le contexte mentionne le supermarché, mais le caviste reste plausible. Seul B répond bien à « combien ».','[{"label": "Du rouge et un peu de blanc.", "is_correct": false, "display_order": 1}, {"label": "Six, comme on s''était dit.", "is_correct": true, "display_order": 2}, {"label": "Pour à peu près trente euros.", "is_correct": false, "display_order": 3}, {"label": "Chez le caviste de la place.", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/edc163b6-628d-4561-9ef1-cabff2bbbb39.mp3','34','fr-FR-DeniseNeural','2026-05-31 16:49:09.356621+02','b70fde1d-95a5-48f1-8b2a-001892218c3b','2026-05-27 17:40:30.299355+02','2026-05-31 16:49:30.134353+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-1000-0000-000000000006','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu reviens tout juste d''Italie, c''est ça ?
[Femme] Oui ! Et toi, tu y étais resté combien de temps déjà ?
[Homme] ...

A. Trois semaines, l''été dernier.
B. À Rome surtout, puis à Florence.
C. Avec deux amis de la fac.
D. Pour voir tous les musées possibles.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu reviens tout juste d''Italie, c''est ça ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui ! Et toi, tu y étais resté combien de temps déjà ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Trois semaines, l''été dernier.<break time="700ms"/>B.<break time="300ms"/>À Rome surtout, puis à Florence.<break time="700ms"/>C.<break time="300ms"/>Avec deux amis de la fac.<break time="700ms"/>D.<break time="300ms"/>Pour voir tous les musées possibles.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour pose le contexte (le retour d''Italie de l''interlocutrice) ; le second contient la question implicite « combien de temps ? », qui porte sur **la durée d''un séjour passé**. Seule A « trois semaines » exprime une durée. B donne le **lieu / les villes visitées** (« où es-tu allé ? »). C donne l''**accompagnant** (« avec qui ? »). D donne le **but du voyage** (« pourquoi y es-tu allé ? »). Piège B1 : A contient « l''été dernier » qui ressemble à un moment, mais la durée principale est bien « trois semaines ».','[{"label": "Trois semaines, l''été dernier.", "is_correct": true, "display_order": 1}, {"label": "À Rome surtout, puis à Florence.", "is_correct": false, "display_order": 2}, {"label": "Avec deux amis de la fac.", "is_correct": false, "display_order": 3}, {"label": "Pour voir tous les musées possibles.", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/8489f1d7-73e3-4ae1-a5c0-15549487f11d.mp3','33','fr-FR-DeniseNeural','2026-05-31 16:49:09.631511+02','b70fde1d-95a5-48f1-8b2a-001892218c3b','2026-05-27 17:40:30.299355+02','2026-05-31 16:49:30.652708+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-1000-0000-000000000007','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] J''étais à un concert génial hier soir.
[Femme] Ah, super ! Tu y étais avec qui ?
[Homme] ...

A. À la salle Pleyel, à Paris.
B. Avec ma sœur et son copain.
C. Jusqu''à minuit, environ.
D. Parce que j''adore ce groupe depuis longtemps.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''étais à un concert génial hier soir.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Ah, super ! Tu y étais avec qui ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>À la salle Pleyel, à Paris.<break time="700ms"/>B.<break time="300ms"/>Avec ma sœur et son copain.<break time="700ms"/>C.<break time="300ms"/>Jusqu''à minuit, environ.<break time="700ms"/>D.<break time="300ms"/>Parce que j''adore ce groupe depuis longtemps.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour mentionne le concert ; le second pose la question implicite « avec qui ? », qui porte sur **l''accompagnant**. Seule B « avec ma sœur et son copain » désigne des personnes. A donne le **lieu** (« où était-ce ? »). C donne un **moment / fin** (« jusqu''à quelle heure ? »). D donne la **cause** (« pourquoi y es-tu allé ? »). Toutes restent dans le champ « concert », ce qui en fait des distracteurs réalistes pour B1.','[{"label": "À la salle Pleyel, à Paris.", "is_correct": false, "display_order": 1}, {"label": "Avec ma sœur et son copain.", "is_correct": true, "display_order": 2}, {"label": "Jusqu''à minuit, environ.", "is_correct": false, "display_order": 3}, {"label": "Parce que j''adore ce groupe depuis longtemps.", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/d5aedab7-2d21-439b-b919-dfc9900d6989.mp3','33','fr-FR-DeniseNeural','2026-05-31 16:49:09.982592+02','b70fde1d-95a5-48f1-8b2a-001892218c3b','2026-05-27 17:40:30.299355+02','2026-05-31 16:49:33.212065+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-1000-0000-000000000008','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] J''hésite entre les deux paires de chaussures pour le mariage.
[Homme] Montre-moi, voir.
[Femme] Alors, tu préfères laquelle ?
[Homme] ...

A. La noire, sans hésiter, elle est plus chic.
B. Chez un cordonnier près du métro.
C. Environ soixante euros la paire.
D. Plutôt pour aller travailler, en fait.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">J''hésite entre les deux paires de chaussures pour le mariage.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Montre-moi, voir.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Alors, tu préfères laquelle ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>La noire, sans hésiter, elle est plus chic.<break time="700ms"/>B.<break time="300ms"/>Chez un cordonnier près du métro.<break time="700ms"/>C.<break time="300ms"/>Environ soixante euros la paire.<break time="700ms"/>D.<break time="300ms"/>Plutôt pour aller travailler, en fait.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le contexte (hésitation entre deux paires, demande d''avis) prépare une question de **choix entre deux options proposées**. La question implicite « tu préfères laquelle ? » appelle l''identification d''une des deux. Seule A « la noire, sans hésiter » désigne un choix. B donne un **lieu d''achat possible** (« où en trouver ? »). C donne un **prix** (« combien coûtent-elles ? »). D donne un **usage** (« pour quoi faire ? »). Piège B1 : B, C, D restent crédibles dans une conversation sur des chaussures, mais aucune ne répond à « laquelle ».','[{"label": "La noire, sans hésiter, elle est plus chic.", "is_correct": true, "display_order": 1}, {"label": "Chez un cordonnier près du métro.", "is_correct": false, "display_order": 2}, {"label": "Environ soixante euros la paire.", "is_correct": false, "display_order": 3}, {"label": "Plutôt pour aller travailler, en fait.", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/71413ccc-e8fa-4f89-a680-6e1dea3a25d5.mp3','36','fr-FR-HenriNeural','2026-05-31 16:49:10.277728+02','b70fde1d-95a5-48f1-8b2a-001892218c3b','2026-05-27 17:40:30.299355+02','2026-05-31 16:49:33.758315+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-1000-0000-000000000009','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] J''ai vu que tu t''étais inscrite à la piscine.
[Femme] Oui, depuis le mois dernier. Et toi, tu y vas à quelle fréquence ?
[Homme] ...

A. Deux fois par semaine, en moyenne.
B. Pendant une heure à chaque séance.
C. Tout près de mon travail.
D. Pour me remettre tranquillement en forme.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''ai vu que tu t''étais inscrite à la piscine.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, depuis le mois dernier. Et toi, tu y vas à quelle fréquence ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Deux fois par semaine, en moyenne.<break time="700ms"/>B.<break time="300ms"/>Pendant une heure à chaque séance.<break time="700ms"/>C.<break time="300ms"/>Tout près de mon travail.<break time="700ms"/>D.<break time="300ms"/>Pour me remettre tranquillement en forme.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour pose le sujet (la piscine), le second précise la durée d''inscription puis pose la question implicite « à quelle fréquence ? », qui porte sur **le rythme, la régularité**. Seule A « deux fois par semaine » exprime une fréquence. B exprime une **durée d''une séance** (« combien de temps restes-tu ? »). C exprime un **lieu** (« où se trouve la piscine ? »). D exprime un **but** (« pourquoi y vas-tu ? »). Piège B1 : A et B mélangent souvent dans l''oreille des candidats, car les deux donnent une indication temporelle.','[{"label": "Deux fois par semaine, en moyenne.", "is_correct": true, "display_order": 1}, {"label": "Pendant une heure à chaque séance.", "is_correct": false, "display_order": 2}, {"label": "Tout près de mon travail.", "is_correct": false, "display_order": 3}, {"label": "Pour me remettre tranquillement en forme.", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/b1c8a511-f1e5-42c9-80c2-6fcd985292ad.mp3','34','fr-FR-DeniseNeural','2026-05-31 16:49:10.639862+02','b70fde1d-95a5-48f1-8b2a-001892218c3b','2026-05-27 17:40:30.299355+02','2026-05-31 16:49:34.404005+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-1000-0000-00000000000a','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu as fini de lire le roman que je t''avais prêté ?
[Femme] Oui, hier soir.
[Homme] Et alors, tu en as pensé quoi ?
[Femme] ...

A. Sur ma table de chevet, tranquillement.
B. En deux semaines, à peu près.
C. À ma grande surprise, beaucoup de bien.
D. Surtout dans le métro, le matin.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu as fini de lire le roman que je t''avais prêté ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, hier soir.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Et alors, tu en as pensé quoi ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Sur ma table de chevet, tranquillement.<break time="700ms"/>B.<break time="300ms"/>En deux semaines, à peu près.<break time="700ms"/>C.<break time="300ms"/>À ma grande surprise, beaucoup de bien.<break time="700ms"/>D.<break time="300ms"/>Surtout dans le métro, le matin.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Les deux premiers tours fixent le contexte (lecture du roman terminée), le troisième pose la question implicite « tu en as pensé quoi ? », qui demande **une opinion, un jugement de valeur**. Seule C « beaucoup de bien » exprime une appréciation. A donne un **lieu de lecture** (« où l''as-tu lu ? »). B donne une **durée de lecture** (« en combien de temps l''as-tu lu ? »). D donne un **moment / contexte de lecture** (« quand le lisais-tu ? »). Piège B1 : trois distracteurs parlent de la lecture mais aucun ne livre un avis.','[{"label": "Sur ma table de chevet, tranquillement.", "is_correct": false, "display_order": 1}, {"label": "En deux semaines, à peu près.", "is_correct": false, "display_order": 2}, {"label": "À ma grande surprise, beaucoup de bien.", "is_correct": true, "display_order": 3}, {"label": "Surtout dans le métro, le matin.", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/2a48d52e-80fd-4294-a2d3-ed62b0518c9c.mp3','35','fr-FR-HenriNeural','2026-05-31 16:49:11.032341+02','b70fde1d-95a5-48f1-8b2a-001892218c3b','2026-05-27 17:40:30.299355+02','2026-05-31 16:49:32.567677+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000001','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu peux me passer ça, sur la table de la cuisine ?
[Homme] Tu parles de quoi, exactement ?
[Femme] ...

A. Sur la grande table, juste là.
B. Pour préparer le repas de ce soir.
C. Le grand bol bleu, à droite.
D. Avec le couvercle en verre.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu peux me passer ça, sur la table de la cuisine ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu parles de quoi, exactement ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Sur la grande table, juste là.<break time="700ms"/>B.<break time="300ms"/>Pour préparer le repas de ce soir.<break time="700ms"/>C.<break time="300ms"/>Le grand bol bleu, à droite.<break time="700ms"/>D.<break time="300ms"/>Avec le couvercle en verre.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','La question « tu parles de quoi ? » demande **l''identification de l''objet** désigné par « ça ». Seule C « le grand bol bleu » nomme un objet. A donne le **lieu** où il se trouve. B donne le **but** de la demande. D donne un **accessoire** qui l''accompagne.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/099a3851-fad2-42c2-a4de-f0347a875fd0.mp3','32','fr-FR-HenriNeural','2026-05-31 16:50:00.136704+02','d1495436-12b3-4a67-bb23-ae36491787c4','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:32.998996+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000002','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] J''ai vu sur ta photo ton nouveau vélo. Il est de quelle couleur en vrai ?
[Homme] ...

A. Un vélo électrique tout neuf.
B. Bleu foncé avec des liserés blancs.
C. Pour mes trajets au travail.
D. Chez un magasin de la Bastille.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">J''ai vu sur ta photo ton nouveau vélo. Il est de quelle couleur en vrai ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Un vélo électrique tout neuf.<break time="700ms"/>B.<break time="300ms"/>Bleu foncé avec des liserés blancs.<break time="700ms"/>C.<break time="300ms"/>Pour mes trajets au travail.<break time="700ms"/>D.<break time="300ms"/>Chez un magasin de la Bastille.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','La question porte sur **la couleur du vélo**. Seule B « bleu foncé avec des liserés blancs » donne une couleur. A donne **le type de vélo** (« quel type ? »). C donne **l''usage** (« pour quoi faire ? »). D donne **le lieu d''achat** (« où l''as-tu acheté ? »).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/1729bff6-fc12-4c46-817b-25727dff1c8f.mp3','30','fr-FR-DeniseNeural','2026-05-31 16:50:00.459272+02','d1495436-12b3-4a67-bb23-ae36491787c4','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:33.589125+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000003','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu pars travailler tôt, dis-moi.
[Homme] Oui, j''ai presque une heure de trajet.
[Femme] Tu y vas comment, en général ?
[Homme] ...

A. À six heures et quart précises.
B. Pour une bonne heure environ.
C. À cause des bouchons constants en voiture.
D. En train, puis à pied jusqu''au bureau.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu pars travailler tôt, dis-moi.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui, j''ai presque une heure de trajet.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu y vas comment, en général ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>À six heures et quart précises.<break time="700ms"/>B.<break time="300ms"/>Pour une bonne heure environ.<break time="700ms"/>C.<break time="300ms"/>À cause des bouchons constants en voiture.<break time="700ms"/>D.<break time="300ms"/>En train, puis à pied jusqu''au bureau.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu y vas comment, en général ? » porte sur **le moyen de transport habituel**. Seule D « en train, puis à pied » nomme les moyens utilisés. A donne **l''heure de départ**. B donne **la durée du trajet**. C donne **une cause expliquant un autre choix** (« pourquoi pas en voiture ? »).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/d7b14534-1944-41d6-820c-ad002a5d3e86.mp3','34','fr-FR-DeniseNeural','2026-05-31 16:50:00.839287+02','d1495436-12b3-4a67-bb23-ae36491787c4','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:30.254166+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000004','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu pars chez le médecin tout à l''heure ?
[Femme] Oui, c''est confirmé.
[Homme] Et à quelle heure exactement ?
[Femme] ...

A. À seize heures trente, normalement.
B. Pour un simple contrôle annuel.
C. Près de la place du marché.
D. Avec mon nouveau généraliste.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu pars chez le médecin tout à l''heure ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, c''est confirmé.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Et à quelle heure exactement ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>À seize heures trente, normalement.<break time="700ms"/>B.<break time="300ms"/>Pour un simple contrôle annuel.<break time="700ms"/>C.<break time="300ms"/>Près de la place du marché.<break time="700ms"/>D.<break time="300ms"/>Avec mon nouveau généraliste.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« À quelle heure exactement ? » porte sur **l''heure précise du rendez-vous**. Seule A « à seize heures trente » donne une heure. B donne **le motif de la consultation**. C donne **le lieu** du cabinet. D donne **l''interlocuteur médical**.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/122d23d0-0297-42e9-9e68-4536a34bca68.mp3','32','fr-FR-HenriNeural','2026-05-31 16:50:01.174271+02','d1495436-12b3-4a67-bb23-ae36491787c4','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:28.353135+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000005','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu as donné ton dîner d''anniversaire hier soir, c''est ça ?
[Homme] Oui, à la maison.
[Femme] Vous étiez combien, finalement ?
[Homme] ...

A. Avec un menu très convivial.
B. Une douzaine, en comptant les enfants.
C. Jusqu''à minuit, environ.
D. Dans le jardin, sous la tonnelle.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu as donné ton dîner d''anniversaire hier soir, c''est ça ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui, à la maison.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Vous étiez combien, finalement ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Avec un menu très convivial.<break time="700ms"/>B.<break time="300ms"/>Une douzaine, en comptant les enfants.<break time="700ms"/>C.<break time="300ms"/>Jusqu''à minuit, environ.<break time="700ms"/>D.<break time="300ms"/>Dans le jardin, sous la tonnelle.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Vous étiez combien ? » porte sur **le nombre de convives**. Seule B « une douzaine » donne un nombre. A donne **la qualité du repas** (« comment était le menu ? »). C donne **l''heure de fin** (« jusqu''à quand ? »). D donne **le lieu** (« où dîniez-vous ? »).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/7a28d13d-f084-48bd-b20a-93a734139728.mp3','35','fr-FR-DeniseNeural','2026-05-31 16:50:01.563885+02','d1495436-12b3-4a67-bb23-ae36491787c4','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:30.785721+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000006','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu m''avais dit que tu cuisinais tout le repas toi-même.
[Femme] Oui, j''ai passé l''après-midi en cuisine.
[Homme] Et tu as préparé quoi, alors ?
[Femme] ...

A. Pendant presque quatre bonnes heures.
B. Pour une douzaine d''invités, je l''ai dit.
C. Un tajine d''agneau aux pruneaux.
D. Avec ma mère qui m''a aidée pour le dessert.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu m''avais dit que tu cuisinais tout le repas toi-même.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, j''ai passé l''après-midi en cuisine.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Et tu as préparé quoi, alors ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Pendant presque quatre bonnes heures.<break time="700ms"/>B.<break time="300ms"/>Pour une douzaine d''invités, je l''ai dit.<break time="700ms"/>C.<break time="300ms"/>Un tajine d''agneau aux pruneaux.<break time="700ms"/>D.<break time="300ms"/>Avec ma mère qui m''a aidée pour le dessert.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu as préparé quoi ? » porte sur **le plat cuisiné**. Seule C « un tajine d''agneau aux pruneaux » nomme un plat. A donne **la durée** passée en cuisine. B donne **le nombre de convives**. D donne **l''aide reçue** (« avec qui as-tu cuisiné ? »).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/d939ce2e-f757-4124-9f29-f7eb45dc18f2.mp3','36','fr-FR-HenriNeural','2026-05-31 16:50:01.996088+02','d1495436-12b3-4a67-bb23-ae36491787c4','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:29.170321+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000007','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu écoutes de la musique au travail ?
[Homme] Tout le temps, ça m''aide à me concentrer.
[Femme] Et quel style, plutôt ?
[Homme] ...

A. Avec un casque sans fil très pratique.
B. Pendant toute la journée, sans discontinuer.
C. Pour rester bien concentré, justement.
D. Du jazz instrumental, surtout.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu écoutes de la musique au travail ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tout le temps, ça m''aide à me concentrer.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Et quel style, plutôt ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Avec un casque sans fil très pratique.<break time="700ms"/>B.<break time="300ms"/>Pendant toute la journée, sans discontinuer.<break time="700ms"/>C.<break time="300ms"/>Pour rester bien concentré, justement.<break time="700ms"/>D.<break time="300ms"/>Du jazz instrumental, surtout.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Quel style, plutôt ? » porte sur **le genre musical écouté**. Seule D « du jazz instrumental » désigne un style. A donne **le matériel utilisé** (« avec quoi écoutes-tu ? »). B donne **la durée d''écoute**. C donne **le but** (« pourquoi en écoutes-tu ? »).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/25fdfe4a-1e33-4384-88ac-b2082aa6ce99.mp3','36','fr-FR-DeniseNeural','2026-05-31 16:50:02.413269+02','d1495436-12b3-4a67-bb23-ae36491787c4','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:31.252123+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000008','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu as appris la nouvelle pour la promotion de ton frère ?
[Femme] Oui, il m''a appelée hier.
[Homme] Tu as ressenti quoi, en l''apprenant ?
[Femme] ...

A. Une vraie fierté pour lui, à vrai dire.
B. À cause de tous ses efforts, je crois.
C. Pendant un long appel téléphonique.
D. Avec ma sœur qui était présente.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu as appris la nouvelle pour la promotion de ton frère ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, il m''a appelée hier.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu as ressenti quoi, en l''apprenant ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Une vraie fierté pour lui, à vrai dire.<break time="700ms"/>B.<break time="300ms"/>À cause de tous ses efforts, je crois.<break time="700ms"/>C.<break time="300ms"/>Pendant un long appel téléphonique.<break time="700ms"/>D.<break time="300ms"/>Avec ma sœur qui était présente.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu as ressenti quoi ? » porte sur **l''émotion personnelle** éprouvée. Seule A « une vraie fierté pour lui » nomme un sentiment. B donne **la cause de la promotion** du frère (« pourquoi a-t-il été promu ? »). C donne **la durée de l''appel**. D donne **l''accompagnante**.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/fdf85567-de6d-4f06-99c1-bd9ea63c442c.mp3','35','fr-FR-HenriNeural','2026-05-31 16:50:02.829674+02','d1495436-12b3-4a67-bb23-ae36491787c4','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:29.719218+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000009','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu as fini par trouver un cadeau d''anniversaire pour ta nièce ?
[Homme] Oui, j''ai eu de la chance.
[Femme] Tu lui as offert quoi, finalement ?
[Homme] ...

A. Pour ses huit ans, comme prévu.
B. Une jolie raquette de tennis.
C. Dans un magasin de sport de la galerie.
D. Avec ma femme, samedi après-midi.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu as fini par trouver un cadeau d''anniversaire pour ta nièce ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui, j''ai eu de la chance.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu lui as offert quoi, finalement ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Pour ses huit ans, comme prévu.<break time="700ms"/>B.<break time="300ms"/>Une jolie raquette de tennis.<break time="700ms"/>C.<break time="300ms"/>Dans un magasin de sport de la galerie.<break time="700ms"/>D.<break time="300ms"/>Avec ma femme, samedi après-midi.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu lui as offert quoi ? » porte sur **la nature de l''objet offert**. Seule B « une jolie raquette de tennis » nomme un cadeau. A donne **l''occasion** (« pour quel motif ? »). C donne **le lieu d''achat**. D donne **l''accompagnement et le moment** de l''achat.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/3fecf5c6-36f1-40fe-a6aa-b435cce02e89.mp3','36','fr-FR-DeniseNeural','2026-05-31 16:50:03.223175+02','d1495436-12b3-4a67-bb23-ae36491787c4','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:31.703728+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-00000000000a','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu reviens de ton week-end à la campagne ?
[Femme] Oui, et franchement, je suis sous le charme.
[Homme] Qu''est-ce qui t''a le plus surprise, là-bas ?
[Femme] ...

A. Pendant deux nuits seulement.
B. Avec mon mari et nos enfants.
C. Le calme absolu de la nuit.
D. Près de Chartres, en Eure-et-Loir.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu reviens de ton week-end à la campagne ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, et franchement, je suis sous le charme.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Qu''est-ce qui t''a le plus surprise, là-bas ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Pendant deux nuits seulement.<break time="700ms"/>B.<break time="300ms"/>Avec mon mari et nos enfants.<break time="700ms"/>C.<break time="300ms"/>Le calme absolu de la nuit.<break time="700ms"/>D.<break time="300ms"/>Près de Chartres, en Eure-et-Loir.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Qu''est-ce qui t''a le plus surprise ? » porte sur **l''élément qui a marqué / étonné**. Seule C « le calme absolu de la nuit » désigne un tel élément. A donne **la durée du séjour**. B donne **les accompagnants**. D donne **le lieu**.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/6419f107-b92a-423d-a863-f9ea2baaba3a.mp3','34','fr-FR-HenriNeural','2026-05-31 16:50:03.645542+02','d1495436-12b3-4a67-bb23-ae36491787c4','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:32.319748+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-00000000000b','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Alors, tes plans pour le week-end qui arrive ?
[Femme] Rien d''extraordinaire, tu sais. Et toi, tu fais quoi ?
[Homme] ...

A. À cause du beau temps annoncé.
B. Avec ma cousine en visite à Paris.
C. Pour me reposer un peu, surtout.
D. Du rangement et un peu de lecture.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Alors, tes plans pour le week-end qui arrive ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Rien d''extraordinaire, tu sais. Et toi, tu fais quoi ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>À cause du beau temps annoncé.<break time="700ms"/>B.<break time="300ms"/>Avec ma cousine en visite à Paris.<break time="700ms"/>C.<break time="300ms"/>Pour me reposer un peu, surtout.<break time="700ms"/>D.<break time="300ms"/>Du rangement et un peu de lecture.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','La question retournée « et toi, tu fais quoi ? » porte sur **les activités prévues**. Seule D « du rangement et un peu de lecture » liste des activités. A donne **une cause / motif** (« pourquoi sortir ? »). B donne **l''accompagnante**. C donne **le but général** (« pour quoi faire ? »).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/3ba23b74-0333-4059-9443-c5158dfe3c6e.mp3','34','fr-FR-DeniseNeural','2026-05-31 16:50:35.656498+02','ea6ea86e-41eb-495d-95da-61a952eb7cba','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:50.269608+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-00000000000c','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu reviens du garage avec ta voiture ?
[Femme] Oui, ils m''ont fait toute la révision.
[Homme] Et ça t''a coûté combien en tout ?
[Femme] ...

A. Près de quatre cents euros, finalement.
B. Pendant presque deux heures de travail.
C. Avec le changement des freins inclus.
D. Chez un garagiste vraiment de confiance.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu reviens du garage avec ta voiture ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, ils m''ont fait toute la révision.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Et ça t''a coûté combien en tout ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Près de quatre cents euros, finalement.<break time="700ms"/>B.<break time="300ms"/>Pendant presque deux heures de travail.<break time="700ms"/>C.<break time="300ms"/>Avec le changement des freins inclus.<break time="700ms"/>D.<break time="300ms"/>Chez un garagiste vraiment de confiance.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Ça t''a coûté combien en tout ? » porte sur **le prix total payé**. Seule A « près de quatre cents euros » donne un montant. B donne **la durée de l''intervention**. C donne **les prestations incluses**. D donne **le lieu / la qualité du garage**.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/240ca5b7-3ee7-4e57-9489-4fb84679220e.mp3','34','fr-FR-HenriNeural','2026-05-31 16:50:36.102083+02','ea6ea86e-41eb-495d-95da-61a952eb7cba','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:41.673495+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-00000000000d','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] J''ai croisé ton nouveau voisin hier matin. Il a l''air sympa. Il fait quoi dans la vie ?
[Homme] ...

A. Depuis quelques mois seulement chez nous.
B. Architecte dans une petite agence parisienne.
C. Au troisième étage, juste au-dessus.
D. Avec sa famille au grand complet.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">J''ai croisé ton nouveau voisin hier matin. Il a l''air sympa. Il fait quoi dans la vie ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Depuis quelques mois seulement chez nous.<break time="700ms"/>B.<break time="300ms"/>Architecte dans une petite agence parisienne.<break time="700ms"/>C.<break time="300ms"/>Au troisième étage, juste au-dessus.<break time="700ms"/>D.<break time="300ms"/>Avec sa famille au grand complet.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Il fait quoi dans la vie ? » porte sur **la profession du voisin**. Seule B « architecte dans une petite agence » nomme un métier. A donne **depuis quand il habite là**. C donne **son étage**. D donne **sa composition familiale**.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/23cdb629-9edc-46b3-9940-858e06b0a267.mp3','33','fr-FR-DeniseNeural','2026-05-31 16:50:36.490446+02','ea6ea86e-41eb-495d-95da-61a952eb7cba','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:48.153019+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-00000000000e','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu m''as parlé d''un rendez-vous important à venir.
[Femme] Oui, un entretien d''embauche très attendu.
[Homme] C''est prévu pour quelle date ?
[Femme] ...

A. Pour un poste de chef de projet.
B. Au siège de l''entreprise à La Défense.
C. Le quinze du mois prochain.
D. Avec deux responsables des ressources humaines.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu m''as parlé d''un rendez-vous important à venir.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, un entretien d''embauche très attendu.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">C''est prévu pour quelle date ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Pour un poste de chef de projet.<break time="700ms"/>B.<break time="300ms"/>Au siège de l''entreprise à La Défense.<break time="700ms"/>C.<break time="300ms"/>Le quinze du mois prochain.<break time="700ms"/>D.<break time="300ms"/>Avec deux responsables des ressources humaines.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« C''est prévu pour quelle date ? » porte sur **la date du rendez-vous**. Seule C « le quinze du mois prochain » donne une date. A donne **le poste visé**. B donne **le lieu de l''entretien**. D donne **les interlocuteurs**.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/7da0d4e5-6acf-4a44-b0fe-ffc8bcb4b000.mp3','34','fr-FR-HenriNeural','2026-05-31 16:50:36.859976+02','ea6ea86e-41eb-495d-95da-61a952eb7cba','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:51.486096+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-00000000000f','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu reviens tout juste de Normandie, je crois ?
[Homme] Oui, trois jours formidables.
[Femme] Vous avez eu quel temps, là-bas ?
[Homme] ...

A. Avec une amie d''enfance et son fils.
B. Pendant le week-end de Pâques exactement.
C. À côté de Deauville, sur la côte.
D. Du soleil presque tout le séjour.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu reviens tout juste de Normandie, je crois ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui, trois jours formidables.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Vous avez eu quel temps, là-bas ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Avec une amie d''enfance et son fils.<break time="700ms"/>B.<break time="300ms"/>Pendant le week-end de Pâques exactement.<break time="700ms"/>C.<break time="300ms"/>À côté de Deauville, sur la côte.<break time="700ms"/>D.<break time="300ms"/>Du soleil presque tout le séjour.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Vous avez eu quel temps ? » porte sur **la météo** pendant le séjour. Seule D « du soleil presque tout le séjour » décrit le temps. A donne **les accompagnants**. B donne **la période** du séjour. C donne **le lieu précis**.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/2f9869ae-a89d-4d03-ba1b-bb80ce0ba0d6.mp3','35','fr-FR-DeniseNeural','2026-05-31 16:50:37.202416+02','ea6ea86e-41eb-495d-95da-61a952eb7cba','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:49.102601+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000010','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu vas souvent voir ta famille en province ?
[Femme] Plusieurs fois par an, oui.
[Homme] C''est à quelle distance, déjà ?
[Femme] ...

A. À environ trois cent cinquante kilomètres.
B. Toutes les six semaines à peu près.
C. En train direct, sans correspondance.
D. Pour passer toutes les fêtes ensemble.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu vas souvent voir ta famille en province ?</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Plusieurs fois par an, oui.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">C''est à quelle distance, déjà ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>À environ trois cent cinquante kilomètres.<break time="700ms"/>B.<break time="300ms"/>Toutes les six semaines à peu près.<break time="700ms"/>C.<break time="300ms"/>En train direct, sans correspondance.<break time="700ms"/>D.<break time="300ms"/>Pour passer toutes les fêtes ensemble.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« C''est à quelle distance ? » porte sur **la distance géographique**. Seule A « à environ trois cent cinquante kilomètres » donne une distance. B donne **la fréquence des visites**. C donne **le moyen de transport**. D donne **le but / l''occasion**.','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/225d77e4-c260-4469-bf5b-63a128d38aa4.mp3','34','fr-FR-HenriNeural','2026-05-31 16:50:37.54323+02','ea6ea86e-41eb-495d-95da-61a952eb7cba','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:52.838095+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000011','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

