INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000013','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tu as bien aimé le repas chez les Dupont, hier ?
[Homme] C''était excellent, vraiment.
[Femme] Tu as préféré quoi, dans tout ce qu''elle a servi ?
[Homme] ...

A. Pour environ une dizaine d''invités.
B. Jusqu''à très tard dans la nuit.
C. Avec les voisins du dessus, aussi.
D. Le tiramisu fait maison, sans hésiter.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu as bien aimé le repas chez les Dupont, hier ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">C''était excellent, vraiment.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu as préféré quoi, dans tout ce qu''elle a servi ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Pour environ une dizaine d''invités.<break time="700ms"/>B.<break time="300ms"/>Jusqu''à très tard dans la nuit.<break time="700ms"/>C.<break time="300ms"/>Avec les voisins du dessus, aussi.<break time="700ms"/>D.<break time="300ms"/>Le tiramisu fait maison, sans hésiter.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Tu as préféré quoi, dans tout ce qu''elle a servi ? » porte sur **le plat favori du repas**. Seule D « le tiramisu fait maison » désigne un plat. A donne **le nombre d''invités**. B donne **la durée de la soirée**. C donne **les autres convives**.','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-DeniseNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/0f231a62-f02e-42bb-b8ed-6847e07969b7.mp3','36','fr-FR-DeniseNeural','2026-05-31 16:50:38.588268+02','ea6ea86e-41eb-495d-95da-61a952eb7cba','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:47.119601+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-2000-0000-000000000014','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] Tu as l''air de bien connaître les habitants de cet immeuble.
[Femme] Oui, j''y vis depuis longtemps.
[Homme] Et qui habite juste en face de toi ?
[Femme] ...

A. Une famille avec deux jeunes enfants.
B. Au troisième étage gauche, comme moi.
C. Depuis bientôt cinq ans, je crois.
D. Pour un loyer relativement modéré.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Tu as l''air de bien connaître les habitants de cet immeuble.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, j''y vis depuis longtemps.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Et qui habite juste en face de toi ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Une famille avec deux jeunes enfants.<break time="700ms"/>B.<break time="300ms"/>Au troisième étage gauche, comme moi.<break time="700ms"/>C.<break time="300ms"/>Depuis bientôt cinq ans, je crois.<break time="700ms"/>D.<break time="300ms"/>Pour un loyer relativement modéré.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','« Qui habite juste en face de toi ? » porte sur **l''identité / la composition du foyer voisin**. Seule A « une famille avec deux jeunes enfants » désigne les occupants. B donne **l''étage** (« où ? »). C donne **depuis quand**. D donne **le loyer** (« combien ? »).','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','PUBLISHED','https://pub-a92171f43ec34a52807a396f17f58ba9.r2.dev/audio/297b9903-e141-420d-a450-e3e4b90ae6cb.mp3','35','fr-FR-HenriNeural','2026-05-31 16:50:38.939931+02','ea6ea86e-41eb-495d-95da-61a952eb7cba','2026-05-27 17:40:30.330267+02','2026-05-31 16:50:50.902666+02','aaaaaaaa-0000-0000-0000-000000000001',NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-3000-0000-000000000001','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Tout le monde a adoré la fête de retraite de papa.
[Homme] Oui, c''était une vraie réussite.
[Femme] Mais dis-moi, comment tu as préparé tout ça ?
[Homme] ...

A. En m''y prenant trois semaines à l''avance, étape par étape.
B. Avec ma sœur et le mari de Camille, surtout.
C. Dans la grande salle de l''ancienne mairie.
D. Pour lui faire vraiment plaisir, tout simplement.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tout le monde a adoré la fête de retraite de papa.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui, c''était une vraie réussite.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Mais dis-moi, comment tu as préparé tout ça ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>En m''y prenant trois semaines à l''avance, étape par étape.<break time="700ms"/>B.<break time="300ms"/>Avec ma sœur et le mari de Camille, surtout.<break time="700ms"/>C.<break time="300ms"/>Dans la grande salle de l''ancienne mairie.<break time="700ms"/>D.<break time="300ms"/>Pour lui faire vraiment plaisir, tout simplement.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Les deux premiers tours valident le succès de la fête ; la question finale « comment tu as préparé tout ça ? » porte sur **la méthode d''organisation**. Seule A « en m''y prenant trois semaines à l''avance, étape par étape » décrit une démarche d''organisation. B donne **l''aide reçue** (« avec qui ? »). C donne **le lieu** de la fête (« où ? »). D donne **le but / motif** (« pour quoi faire ? »).','[{"label": "A", "is_correct": true, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.375755+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-3000-0000-000000000002','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] J''aimerais bien aller au cinéma ce week-end, mais je ne sais pas quoi voir.
[Femme] Tu me recommandes quel film, alors ?
[Homme] ...

A. Vers vingt heures, en séance du soir.
B. La dernière comédie de Klapisch, sans hésiter.
C. Au cinéma du quartier des Halles, c''est sympa.
D. Avec ta sœur, elle adore ce genre de chose.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''aimerais bien aller au cinéma ce week-end, mais je ne sais pas quoi voir.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Tu me recommandes quel film, alors ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Vers vingt heures, en séance du soir.<break time="700ms"/>B.<break time="300ms"/>La dernière comédie de Klapisch, sans hésiter.<break time="700ms"/>C.<break time="300ms"/>Au cinéma du quartier des Halles, c''est sympa.<break time="700ms"/>D.<break time="300ms"/>Avec ta sœur, elle adore ce genre de chose.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour expose l''embarras (quoi voir ?) ; la question « tu me recommandes quel film ? » appelle **le titre / la désignation d''un film**. Seule B « la dernière comédie de Klapisch » désigne un film. A donne **l''heure de séance**. C donne **le cinéma conseillé** (« où aller ? »). D donne **un accompagnant suggéré** (« avec qui y aller ? »).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": true, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.375755+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-3000-0000-000000000003','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Homme] J''ai annoncé à ma mère que je partais m''installer à Lyon.
[Femme] Ah, enfin ! Tu lui as dit hier ?
[Homme] Oui, au téléphone. Et toi, tu sais comment elle a réagi ?
[Femme] ...

A. Pendant un long appel, jusqu''à minuit.
B. À cause du nouveau travail qui t''attend là-bas.
C. Avec beaucoup d''émotion, mais sans s''opposer.
D. Chez ma tante, où on était toutes les deux.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''ai annoncé à ma mère que je partais m''installer à Lyon.</prosody></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Ah, enfin ! Tu lui as dit hier ?</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Oui, au téléphone. Et toi, tu sais comment elle a réagi ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Pendant un long appel, jusqu''à minuit.<break time="700ms"/>B.<break time="300ms"/>À cause du nouveau travail qui t''attend là-bas.<break time="700ms"/>C.<break time="300ms"/>Avec beaucoup d''émotion, mais sans s''opposer.<break time="700ms"/>D.<break time="300ms"/>Chez ma tante, où on était toutes les deux.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Les deux premiers tours posent l''annonce (départ à Lyon) ; la question « comment elle a réagi ? » porte sur **la nature de la réaction**. Seule C « avec beaucoup d''émotion, mais sans s''opposer » décrit une réaction. A donne **la durée de l''appel** (« combien de temps avez-vous parlé ? »). B donne **la cause du départ** (« pourquoi pars-tu ? »). D donne **le lieu où la nouvelle a été apprise** (« où l''as-tu apprise ? »).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": true, "display_order": 3}, {"label": "D", "is_correct": false, "display_order": 4}]','fr-FR-DeniseNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.375755+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-3000-0000-000000000004','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Je dors très mal depuis deux semaines, j''en peux plus.
[Homme] Qu''est-ce que tu me conseilles, toi qui as eu le même problème ?
[Femme] ...

A. Depuis bientôt un mois, dans mon cas.
B. À cause du stress, sans doute, comme moi.
C. Pour retrouver enfin une vraie qualité de sommeil.
D. D''essayer la tisane et de ranger ton téléphone le soir.','<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.</prosody></voice><break time="1500ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Je dors très mal depuis deux semaines, j''en peux plus.</prosody></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Qu''est-ce que tu me conseilles, toi qui as eu le même problème ?</prosody></voice><break time="1000ms"/><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">A.<break time="300ms"/>Depuis bientôt un mois, dans mon cas.<break time="700ms"/>B.<break time="300ms"/>À cause du stress, sans doute, comme moi.<break time="700ms"/>C.<break time="300ms"/>Pour retrouver enfin une vraie qualité de sommeil.<break time="700ms"/>D.<break time="300ms"/>D''essayer la tisane et de ranger ton téléphone le soir.</prosody></voice></speak>','Écoutez le document sonore, puis choisissez la bonne réponse parmi les propositions A, B, C ou D.','Le premier tour pose le problème (mauvais sommeil) ; la question « qu''est-ce que tu me conseilles ? » appelle **une recommandation concrète d''action**. Seule D « d''essayer la tisane et de ranger ton téléphone » formule un conseil. A donne **la durée du problème** chez le locuteur (« depuis combien de temps ? »). B donne **la cause supposée** (« pourquoi tu dors mal ? »). C donne **le but visé** (« pour quoi faire ? »).','[{"label": "A", "is_correct": false, "display_order": 1}, {"label": "B", "is_correct": false, "display_order": 2}, {"label": "C", "is_correct": false, "display_order": 3}, {"label": "D", "is_correct": true, "display_order": 4}]','fr-FR-HenriNeural','TEXT_VALIDATED',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:40:30.375755+02',NULL,NULL,NULL);
INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-3000-0000-000000000005','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

[Femme] Alors, ton voyage en Andalousie, raconte un peu !
[Homme] On a vraiment beaucoup vu, c''était dense.
[Femme] Et tu as préféré quel endroit, finalement ?
[Homme] ...

A. L''Alhambra de Grenade, sans aucune hésitation.
