INSERT INTO audio_question_draft (id, difficulty, competence_code, theme_id, transcript_text, ssml_text, statement, explanation, choices, voice_recommended, status, audio_url, audio_duration_sec, audio_voice_used, audio_generated_at, batch_id, created_at, audio_validated_at, audio_validated_by, rejection_reason) VALUES ('66666666-00b1-3000-0000-00000000000a','B1','co_dialogue_b1_implicite','22222222-0000-0000-0000-000000000001','Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.

